5	/**
6	 * Возвращает массив кодов ошибок при проверке данных покупателя.
7	 * "email" – нарушена валидность email.
8	 * "phone" – нарушена валидность телефона.
9	 * Ошибки возвращаются в строгоом порядке: сначала email, затем phone.
10	 */
11	export function validateCustomer(customer: Customer): string[] {
12	  const errors: string[] = [];
13	
14	  // ----- email -----
15	  const email = customer.email;
16	  let emailValid = true;
17	
18	  // отсутствие пробелов
19	  if (email.includes(' ')) {
20	    emailValid = false;
21	  } else {
22	    const parts = email.split('@');
23	    if (parts.length !== 2) {
24	      emailValid = false;
25	    } else {
26	      const [local, domain] = parts;
27	      if (local === '' || domain === '') {
28	        emailValid = false;
29	      } else {
30	        // домен должен содержать точку, но не начинаться или завершаться ею
31	        if (!domain.includes('.')) {
32	          emailValid = false;
33	        } else if (domain.startsWith('.') || domain.endsWith('.')) {
34	          emailValid = false;
35	        }
36	      }
37	    }
38	  }
39	
40	  if (!emailValid) {
41	    errors.push('email');
42	  }
43	
44	  // ----- phone -----
45	  const phone = customer.phone;
46	  // +7 + 10 digits OR 8 + 10 digits, no other symbols
47	  const phoneRegex = /^(\+7|8)\d{10}$/;
48	  if (!phoneRegex.test(phone)) {
49	    errors.push('phone');
50	  }
51	
52	  return errors;
53	}
